macro_rules! deps {
    () => {
        Open01!();
        Distribution!();
        Rng!();
        Alphabetic!();
        Alphanumeric!();
        OpenClosed01!();
        Uniform!();
    };
}

macro_rules! StandardUniform {
    () => {
        deps!();
        # [doc = " The Standard Uniform distribution"] # [doc = ""] # [doc = " This [`Distribution`] is the *standard* parameterization of [`Uniform`]. Bounds"] # [doc = " are selected according to the output type."] # [doc = ""] # [doc = " Assuming the provided `Rng` is well-behaved, these implementations"] # [doc = " generate values with the following ranges and distributions:"] # [doc = ""] # [doc = " * Integers (`i8`, `i32`, `u64`, etc.) are uniformly distributed"] # [doc = "   over the whole range of the type (thus each possible value may be sampled"] # [doc = "   with equal probability)."] # [doc = " * `char` is uniformly distributed over all Unicode scalar values, i.e. all"] # [doc = "   code points in the range `0...0x10_FFFF`, except for the range"] # [doc = "   `0xD800...0xDFFF` (the surrogate code points). This includes"] # [doc = "   unassigned/reserved code points."] # [doc = "   For some uses, the [`Alphanumeric`] or [`Alphabetic`] distribution will be more"] # [doc = "   appropriate."] # [doc = " * `bool` samples `false` or `true`, each with probability 0.5."] # [doc = " * Floating point types (`f32` and `f64`) are uniformly distributed in the"] # [doc = "   half-open range `[0, 1)`. See also the [notes below](#floating-point-implementation)."] # [doc = " * Wrapping integers ([`Wrapping<T>`]), besides the type identical to their"] # [doc = "   normal integer variants."] # [doc = " * Non-zero integers ([`NonZeroU8`]), which are like their normal integer"] # [doc = "   variants but cannot sample zero."] # [doc = ""] # [doc = " The `StandardUniform` distribution also supports generation of the following"] # [doc = " compound types where all component types are supported:"] # [doc = ""] # [doc = " * Tuples (up to 12 elements): each element is sampled sequentially and"] # [doc = "   independently (thus, assuming a well-behaved RNG, there is no correlation"] # [doc = "   between elements)."] # [doc = " * Arrays `[T; n]` where `T` is supported. Each element is sampled"] # [doc = "   sequentially and independently. Note that for small `T` this usually"] # [doc = "   results in the RNG discarding random bits; see also [`Rng::fill`] which"] # [doc = "   offers a more efficient approach to filling an array of integer types"] # [doc = "   with random data."] # [doc = " * SIMD types (requires [`simd_support`] feature) like x86's [`__m128i`]"] # [doc = "   and `std::simd`'s [`u32x4`], [`f32x4`] and [`mask32x4`] types are"] # [doc = "   effectively arrays of integer or floating-point types. Each lane is"] # [doc = "   sampled independently, potentially with more efficient random-bit-usage"] # [doc = "   (and a different resulting value) than would be achieved with sequential"] # [doc = "   sampling (as with the array types above)."] # [doc = ""] # [doc = " ## Custom implementations"] # [doc = ""] # [doc = " The [`StandardUniform`] distribution may be implemented for user types as follows:"] # [doc = ""] # [doc = " ```"] # [doc = " # #![allow(dead_code)]"] # [doc = " use rand::Rng;"] # [doc = " use rand::distr::{Distribution, StandardUniform};"] # [doc = ""] # [doc = " struct MyF32 {"] # [doc = "     x: f32,"] # [doc = " }"] # [doc = ""] # [doc = " impl Distribution<MyF32> for StandardUniform {"] # [doc = "     fn sample<R: Rng + ?Sized>(&self, rng: &mut R) -> MyF32 {"] # [doc = "         MyF32 { x: rng.random() }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## Example usage"] # [doc = " ```"] # [doc = " use rand::prelude::*;"] # [doc = " use rand::distr::StandardUniform;"] # [doc = ""] # [doc = " let val: f32 = rand::rng().sample(StandardUniform);"] # [doc = " println!(\"f32 from [0, 1): {}\", val);"] # [doc = " ```"] # [doc = ""] # [doc = " # Floating point implementation"] # [doc = " The floating point implementations for `StandardUniform` generate a random value in"] # [doc = " the half-open interval `[0, 1)`, i.e. including 0 but not 1."] # [doc = ""] # [doc = " All values that can be generated are of the form `n * ε/2`. For `f32`"] # [doc = " the 24 most significant random bits of a `u32` are used and for `f64` the"] # [doc = " 53 most significant bits of a `u64` are used. The conversion uses the"] # [doc = " multiplicative method: `(rng.gen::<$uty>() >> N) as $ty * (ε/2)`."] # [doc = ""] # [doc = " See also: [`Open01`] which samples from `(0, 1)`, [`OpenClosed01`] which"] # [doc = " samples from `(0, 1]` and `Rng::random_range(0..1)` which also samples from"] # [doc = " `[0, 1)`. Note that `Open01` uses transmute-based methods which yield 1 bit"] # [doc = " less precision but may perform faster on some architectures (on modern Intel"] # [doc = " CPUs all methods have approximately equal performance)."] # [doc = ""] # [doc = " [`Uniform`]: uniform::Uniform"] # [doc = " [`Wrapping<T>`]: std::num::Wrapping"] # [doc = " [`NonZeroU8`]: std::num::NonZeroU8"] # [doc = " [`__m128i`]: https://doc.rust-lang.org/core/arch/x86/struct.__m128i.html"] # [doc = " [`u32x4`]: std::simd::u32x4"] # [doc = " [`f32x4`]: std::simd::f32x4"] # [doc = " [`mask32x4`]: std::simd::mask32x4"] # [doc = " [`simd_support`]: https://github.com/rust-random/rand#crate-features"] # [derive (Clone , Copy , Debug , Default)] # [cfg_attr (feature = "serde" , derive (serde :: Serialize , serde :: Deserialize))] pub struct StandardUniform ;
    };
}

StandardUniform!()